# HLCO Safety Relay 3D (WebDev relay3d/*): READ ONLY relay state for the three.js page, and the locally served static files.
# Generated by .cursor/tasks/safety-relay-3d/build.py (docs/safety-relay-3d.md) - edit the builder's src, not this copy.
# Nothing here writes a tag: system.tag.readBlocking only, and only below [default]Boars_Head/ (never [RCP1] or
# [default]_RCP1_). Callers check the login first (shared.WebAuth.perspectiveUser).
import re

DEVICE_FOLDER = "[default]Boars_Head/GrovePort/Machine Room/SafetyRelays/"
SITE_PREFIX = "[default]Boars_Head/"
LIST_TAG = "[default]_Config/PLCs/List"
_NAME = re.compile(r"^[A-Za-z0-9 _\-]{1,60}$")
_PLC = re.compile(r"^[A-Za-z0-9_\-]{1,40}$")
CATALOG = "440C-CR30-22BBB/A"
# module input assembly members (device UDT: IO -> PLC/CR30_Input), BOOLs
POINTS = ["Pt%02dData" % i for i in range(10)] + ["Pt18Data", "Pt19Data", "Pt20Data", "Pt21Data"] \
    + ["Plugin2InPt%02dData" % i for i in range(4)] + ["Plugin2OutPt%02dData" % i for i in range(4)] \
    + ["SOF01ResetRequired", "SOF02ResetRequired", "SOF05", "SOF06", "RunMode", "MinorFault"]
CODES = ["MajorFaultCode", "MajorFaultType"]
FILES = {"relay3d.js": "text/javascript; charset=utf-8", "relay3d.css": "text/css; charset=utf-8",
         "demo-state.json": "application/json; charset=utf-8", "view.html": "text/html; charset=utf-8"}
LIB_REL = "projects/BH/com.inductiveautomation.webdev/resources/relay3d/lib/"


def param(request, key, default=""):
	try:
		v = (request.get("params") or {}).get(key)
	except:
		v = None
	if v is None:
		return default
	if not isinstance(v, basestring):
		try:
			v = v[0] if len(v) else default
		except:
			pass
	return unicode(v)


def devicePath(name):
	if not _NAME.match(name or ""):
		return None
	path = DEVICE_FOLDER + name
	return path if path.startswith(SITE_PREFIX) else None


def screwType(plc):
	"""'phillips' (default) or 'flat': the same Designer-only screwType the 3D rack reads from _Config/PLCs/List (this PLC's entry)."""
	try:
		v = system.tag.readBlocking([LIST_TAG])[0].value
		if hasattr(v, "toDict"):
			v = v.toDict()
		lst = system.util.jsonDecode(system.util.jsonEncode(v)) or {}
		for e in lst.get("plcs") or []:
			if unicode(e.get("name")) == plc:
				return "flat" if unicode(e.get("screwType") or "").strip().lower() == "flat" else "phillips"
	except:
		pass
	return "phillips"


def _good(qv):
	try:
		return qv.quality.isGood()
	except:
		return False


def _bool(qv):
	if not _good(qv) or qv.value is None:
		return None
	try:
		return 1 if bool(qv.value) else 0
	except:
		return None


def state(request):
	name = param(request, "device", "HLCO Safety Relay")
	plc = param(request, "plc", "RCP1")
	base = devicePath(name)
	if base is None:
		return {"ok": False, "reason": "Unknown Device", "device": name}
	if not _PLC.match(plc):
		plc = "RCP1"
	paths = [base + "/IO/ConnectionFaulted", base + "/PlcMajorFault", base + "/PlcResetAlm"] \
		+ [base + "/IO/" + p for p in POINTS] + [base + "/IO/" + c for c in CODES]
	vals = system.tag.readBlocking(paths)
	cf = vals[0]
	comm = _good(cf) and cf.value is not None and not bool(cf.value)
	v, i = {}, 3
	for p in POINTS:
		v[p] = _bool(vals[i]) if comm else None
		i += 1
	codes = {}
	for c in CODES:
		q = vals[i]
		try:
			codes[c] = (int(q.value) if _good(q) and q.value is not None else None) if comm else None
		except:
			codes[c] = None
		i += 1
	fault = _bool(vals[1]) if comm else None
	return {"ok": True, "device": name, "plc": plc, "comm": bool(comm), "catalog": CATALOG, "screwType": screwType(plc),
	        "ts": system.date.toMillis(system.date.now()), "run": bool(v.get("RunMode")) if comm else None,
	        "fault": bool(fault) if fault is not None else None,
	        "resetAlm": (bool(_bool(vals[2])) if _bool(vals[2]) is not None else None) if comm else None,
	        "v": v, "codes": codes}


def _libDir(request):
	try:
		d = request["context"].getSystemManager().getDataDir().getAbsolutePath()
	except:
		d = "/usr/local/bin/ignition/data"
	return d.rstrip("/") + "/" + LIB_REL


def serveFile(request, name):
	"""Bytes of one whitelisted relay3d/lib file (read from the project folder on the gateway; cached per mtime)."""
	from java.io import File
	from java.nio.file import Files
	ctype = FILES.get(name)
	if ctype is None:
		return None
	f = File(_libDir(request) + name)
	if not f.isFile():
		return None
	key = "bh.relay3d.file." + name
	store = system.util.getGlobals()
	hit = store.get(key)
	if hit is None or hit[0] != f.lastModified():
		hit = (f.lastModified(), Files.readAllBytes(f.toPath()))
		store[key] = hit
	return {"bytes": hit[1], "contentType": ctype}
